use std::{collections::HashSet,hint::black_box,time::Instant};
fn main(){let ips:Vec<[u8;4]>=(0..256u32).map(|i|(0x0a000000+i).to_be_bytes()).collect();let set:HashSet<[u8;4]>=ips.iter().copied().collect();let rows:Vec<[u8;4]>=(0..10000u32).map(|i|if i%10==0{ips[i as usize%256]}else{(0xc6120000+i).to_be_bytes()}).collect();for trial in 0..3{let start=Instant::now();let mut n=0;for _ in 0..100{for address in &rows{n+=black_box(&ips).iter().any(|ip|ip==black_box(address)) as usize;}}let linear=start.elapsed();let start=Instant::now();let mut m=0;for _ in 0..100{for address in &rows{m+=black_box(&set).contains(black_box(address)) as usize;}}let hashed=start.elapsed();assert_eq!(n,m);println!("trial={trial} linear_ms={} hashed_ms={} matches={n}",linear.as_secs_f64()*1000.,hashed.as_secs_f64()*1000.);}}
